Security::start();Security::requireRole(['reviewer','admin','super_admin']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authority Campaigns | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}main{max-width:1300px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px}.panel{margin-top:18px}.row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:70px}label{display:block;font-size:12px;font-weight:700;margin:8px 0 4px}button{padding:9px 12px;border:0;border-radius:8px;background:#173b63;color:#fff;cursor:pointer}.secondary{background:#475569}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{padding:9px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top;font-size:13px}.muted{color:#64748b}.pill{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:11px}@media(max-width:900px){.grid,.row{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><main><p><a href="/authority-admin">← Authority & Backlinks</a> · <a href="/research/software-evidence-benchmark">Research benchmark</a></p><h1>Research-led Authority Campaigns</h1><p class="muted">Turn verified TechSelectAI assets into controlled outreach campaigns. Record what actually happened; do not mark authority as gained until an external publication/backlink is independently verified.</p><section class="panel"><h2>Create campaign</h2><div class="row"><div><label>Name</label><input id="name" value="Software Evidence Benchmark outreach"></div><div><label>Asset path</label><input id="asset_path" value="/research/software-evidence-benchmark"></div><div><label>Status</label><select id="status"><option>draft</option><option>active</option><option>paused</option><option>completed</option></select></div></div><label>Objective</label><input id="objective" value="Earn legitimate editorial mentions and citations to original TechSelectAI research."><label>Target audience</label><input id="target_audience" value="Relevant software, enterprise IT, MENA technology and research publications"><p><button onclick="createCampaign()">Create campaign</button></p><div id="msg"></div></section><section class="panel"><h2>Campaigns</h2><div id="campaigns" class="grid"></div></section><section class="panel" id="detail" hidden><h2 id="detailTitle"></h2><p id="detailMeta" class="muted"></p><div class="row"><div><label>Add authority prospect</label><select id="source"></select></div><div><label>Editorial angle</label><input id="angle" placeholder="Why this asset is relevant to this publication"></div><div><label>Next action</label><input id="next_action_at" type="datetime-local"></div></div><p><button onclick="addTarget()">Add target</button></p><table><thead><tr><th>Target</th><th>Priority</th><th>Status</th><th>Angle</th><th>Outcome</th></tr></thead><tbody id="targets"></tbody></table></section></main><script>
let campaigns=[],sources=[],current=null;function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':localStorage.getItem('csrf')||''};let r=await fetch(url,opt),d=await r.json().catch(()=>({error:'Invalid response'}));if(!r.ok)throw new Error(d.error||'Request failed');return d}function note(t,ok=true){let m=document.getElementById('msg');m.textContent=t;m.style.color=ok?'#166534':'#b91c1c'}async function load(){try{let [c,s]=await Promise.all([api('/api/authority-campaigns'),api('/api/authority-sources')]);campaigns=c.campaigns||[];sources=s.sources||[];document.getElementById('campaigns').innerHTML=campaigns.map(x=>`<div class="card"><span class="pill">${esc(x.status)}</span><h3>${esc(x.name)}</h3><p class="muted">${esc(x.asset_path)}</p><p>${+x.targets||0} targets · ${+x.contacted||0} contacted · ${+x.active_backlinks||0} active links</p><button onclick="openCampaign(${x.id})">Open</button></div>`).join('')||'<p>No campaigns yet.</p>';document.getElementById('source').innerHTML=sources.map(x=>`<option value="${x.id}">${esc(x.source_name)} — ${esc(x.domain)} (${esc(x.readiness_status)})</option>`).join('')}catch(e){note(e.message,false)}}async function createCampaign(){try{let b={name:name.value,asset_path:asset_path.value,status:status.value,objective:objective.value,target_audience:target_audience.value};let d=await api('/api/authority-campaigns',{method:'POST',body:JSON.stringify(b)});note('Campaign created and audited.');await load();openCampaign(d.campaign.id)}catch(e){note(e.message,false)}}async function openCampaign(id){try{let d=await api('/api/authority-campaigns/'+id);current=d.campaign;detail.hidden=false;detailTitle.textContent=current.name;detailMeta.textContent=current.objective+' · '+current.asset_path;targets.innerHTML=(current.targets||[]).map(x=>`<tr><td><strong>${esc(x.source_name)}</strong><br>${esc(x.domain)}</td><td>${esc(x.priority_score)}</td><td>${esc(x.status)}</td><td>${esc(x.angle||'—')}</td><td>${x.backlink_status==='active'?'<strong>Active backlink</strong>':esc(x.backlink_status||'not published')}<br><button class="secondary" onclick="eventPrompt(${x.id})">Record event</button></td></tr>`).join('')}catch(e){note(e.message,false)}}async function addTarget(){if(!current)return;try{await api('/api/authority-campaigns/'+current.id+'/targets',{method:'POST',body:JSON.stringify({authority_source_id:+source.value,angle:angle.value,next_action_at:next_action_at.value})});await openCampaign(current.id)}catch(e){note(e.message,false)}}async function eventPrompt(id){let type=prompt('Event: contacted, follow_up, reply, accepted, declined, published, backlink_verified, backlink_lost, note','contacted');if(!type)return;let channel=prompt('Channel: email, form, linkedin, partner, vendor, customer, editorial, other','email')||'';let notes=prompt('Notes / response summary','')||'';try{await api('/api/authority-campaign-targets/'+id+'/events',{method:'POST',body:JSON.stringify({event_type:type,channel,notes})});await openCampaign(current.id);await load()}catch(e){note(e.message,false)}}load();
</script></body></html>